---auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
---dm::fda::TruncatedHierarchicalBSpline thb(dm::fda::TensorBSpline(b, {0.0, 1.0}));
---thb.refine(thb.root(), 0);
---std::print("{}\n", thb.basis_size()); // 3
