function datamunge.inside_clip_edge(p, edge_a, edge_b) end

---Clips `subject` (any simple polygon, convex or not) against `clip` (Sutherland-
---Hodgman) and returns their intersection as a new polygon. `clip` MUST be convex
---AND counterclockwise-ordered (exactly what convex_hull() produces) -- the algorithm
---processes it one directed edge at a time, keeping only the subject-polygon portion
---to the left of every edge, so a clockwise or non-convex clip polygon silently
---produces a wrong (or empty) result rather than an error. Returns an empty polygon
---if the two don't overlap at all.
---@param subject datamunge.Point2D[]
---@param clip datamunge.Point2D[]
---@return datamunge.Point2D[]
function datamunge.clip_polygon(subject, clip) end

---C++ `datamunge::geometry::detail::point_in_triangle`
---@param p datamunge.Point2D
---@param a datamunge.Point2D
---@param b datamunge.Point2D
---@param c datamunge.Point2D
---@return boolean
function datamunge.point_in_triangle(p, a, b, c) end

---Triangulates a SIMPLE polygon (convex or not, but not self-intersecting) by ear
---clipping: repeatedly finds a "ear" -- a convex vertex whose neighbor-triangle
---contains no other polygon vertex -- clips it off as one output triangle, and
---repeats on the remaining (n-1)-vertex polygon. O(n^3) worst case (each of the O(n)
---clipped ears requires an O(n) scan to verify, each vertex check O(1)) -- unlike
---delaunay_triangulation() (which only sees an unordered point SET), this respects
---the polygon's actual boundary, so it correctly handles concave (non-convex) shapes.
---Every triangle's vertices are indices into `polygon`. Works for any winding order
---(detects and internally corrects clockwise input). Returns empty for fewer than 3
---vertices; a triangle input returns itself unchanged.
---@param polygon datamunge.Point2D[]
---@return datamunge.Triangle[]
function datamunge.triangulate_polygon(polygon) end

---The diameter of a point set: the farthest pair of points, by Euclidean distance.
---The farthest pair is always a pair of convex hull vertices, so this computes the
---hull first (convex_hull()) and then searches only among its (typically far fewer)
---vertices -- brute-force O(h^2) over the hull rather than the classical O(h)
---two-pointer rotating-calipers walk, the same "correct and simple over asymptotically
---optimal" tradeoff this module already makes for closest_pair(). Throws
---std::invalid_argument for fewer than 2 distinct points.
---@param points datamunge.Point2D[]
---@return datamunge.DiameterResult
function datamunge.polygon_diameter(points) end

---The minimum-AREA bounding rectangle of a point set (not necessarily axis-aligned).
---By a classical theorem, the optimal rectangle always has one side collinear with a
---convex hull edge -- so this computes the hull, then for each hull edge, measures the
---bounding rectangle aligned with that edge's direction (projecting every hull point
---onto the edge direction and its perpendicular), keeping the smallest-area result.
---O(h^2) (h = hull size): the classical rotating-calipers formulation does this in
---O(h) via incrementally-advanced support points, but re-projecting from scratch for
---every edge is far simpler to get right and, again, this module's established
---complexity/simplicity tradeoff. Throws std::invalid_argument if the hull has fewer
---than 3 vertices (no well-defined minimum-area rectangle for a degenerate point set).
---@param points datamunge.Point2D[]
---@return datamunge.MinimumBoundingRectangle
function datamunge.minimum_bounding_rectangle(points) end

---C++ `datamunge::geometry::detail::point_to_line_distance`
---@param p datamunge.Point2D
---@param a datamunge.Point2D
---@param b datamunge.Point2D
---@return number
function datamunge.point_to_line_distance(p, a, b) end

---Simplifies a polyline (Douglas-Peucker): recursively keeps only the point(s)
---farthest from the current baseline segment whenever that distance exceeds
---`epsilon`, discarding everything closer. Fewer than 3 points are returned
---unchanged (nothing to simplify).
---@param points datamunge.Point2D[]
---@param epsilon number
---@return datamunge.Point2D[]
function datamunge.simplify_polyline(points, epsilon) end

---C++ `datamunge::geometry::detail::circumcenter`
---@param a datamunge.Point2D
---@param b datamunge.Point2D
---@param c datamunge.Point2D
---@return datamunge.Point2D
function datamunge.circumcenter(a, b, c) end

---The Voronoi diagram of `points`, computed as the dual of their Delaunay
---triangulation (delaunay_triangulation()) -- see VoronoiDiagram's cells field for
---the important caveat about unbounded cells at the convex hull boundary. Fewer than
---3 points produce an empty diagram (matching delaunay_triangulation()).
---@param points datamunge.Point2D[]
---@return datamunge.VoronoiDiagram
function datamunge.voronoi_diagram(points) end

---Reads an uncompressed (BI_RGB) Windows BMP file as an RGB image. Accepts 24-bit
---(BGR), 32-bit (BGRx -- the 4th byte is ignored, never treated as alpha, since plain
---BITMAPINFOHEADER 32-bit files don't reliably agree on what that byte means), and
---8-bit palette (indexed-color) files; any other bit depth or a compressed
---(non-BI_RGB) file throws std::runtime_error.
---@param path string
---@return datamunge.Image
function datamunge.read_bmp(path) end

---Writes `img` as an uncompressed 24-bit BGR Windows BMP (BITMAPINFOHEADER, BI_RGB),
---converting to RGB first if it isn't already (see to_rgb()) -- any alpha channel is
---dropped, matching write_ppm()'s same RGB-only-on-disk tradeoff.
---@param img datamunge.Image
---@param path string
function datamunge.write_bmp(img, path) end

---C++ `datamunge::image::detail::set_pixel_clipped`
---@param img datamunge.Image
---@param x integer
---@param y integer
---@param color datamunge.Pixel
function datamunge.set_pixel_clipped(img, x, y, color) end

---C++ `datamunge::image::detail::stamp`
---@param img datamunge.Image
---@param cx integer
---@param cy integer
---@param color datamunge.Pixel
---@param thickness integer
function datamunge.stamp(img, cx, cy, color, thickness) end

---Draws a straight line from (x0,y0) to (x1,y1) directly onto `img` (Bresenham's
---integer algorithm). `thickness` > 1 stamps a (thickness x thickness) square at
---every line pixel -- simple, not a true round/mitered stroke, but sufficient for this
---module's scope. Points (and any square stamps) outside `img's` bounds are silently
---clipped rather than throwing, matching typical drawing-library behavior for
---partially-offscreen shapes.
---@param img datamunge.Image
---@param x0 integer
---@param y0 integer
---@param x1 integer
---@param y1 integer
---@param color datamunge.Pixel
---@param thickness? integer (default: `1`)
function datamunge.draw_line(img, x0, y0, x1, y1, color, thickness) end

---Draws the rectangle with corners (x0,y0) and (x1,y1) (either diagonal order works)
---onto `img`, either as a one-pixel-wide outline or filled solid.
---@param img datamunge.Image
---@param x0 integer
---@param y0 integer
---@param x1 integer
---@param y1 integer
---@param color datamunge.Pixel
---@param filled? boolean (default: `false`)
function datamunge.draw_rectangle(img, x0, y0, x1, y1, color, filled) end

---Draws a circle of the given `radius` centered at (cx,cy) onto `img`, either as a
---one-pixel-wide outline (the midpoint circle algorithm) or filled solid (bounding-box
---scan with a squared-distance test).
---@param img datamunge.Image
---@param cx integer
---@param cy integer
---@param radius integer
---@param color datamunge.Pixel
---@param filled? boolean (default: `false`)
function datamunge.draw_circle(img, cx, cy, radius, color, filled) end

---Draws the polygon defined by `points` (in order, implicitly closed back to the
---first point) onto `img`. Outline mode connects consecutive vertices with
---draw_line(); filled mode uses a standard even-odd scanline fill. Fewer than 3 points
---draws nothing.
---@param img datamunge.Image
---@param points ([integer, integer])[]
---@param color datamunge.Pixel
---@param filled? boolean (default: `false`)
function datamunge.draw_polygon(img, points, color, filled) end

---Reads a binary (P6) Netpbm color image. Only 8-bit-per-channel (maxval <= 255)
---files are supported. Throws std::runtime_error on a malformed file or I/O failure.
---@param path string
---@return datamunge.Image
function datamunge.read_ppm(path) end

---Writes `img` as a binary (P6) Netpbm color image, converting to RGB first if it
---isn't already (see to_rgb()).
---@param img datamunge.Image
---@param path string
function datamunge.write_ppm(img, path) end

---Reads a binary (P5) Netpbm grayscale image. Only 8-bit (maxval <= 255) files are
---supported. Throws std::runtime_error on a malformed file or I/O failure.
---@param path string
---@return datamunge.Image
function datamunge.read_pgm(path) end

---Writes `img` as a binary (P5) Netpbm grayscale image, converting to Grayscale first
---if it isn't already (see to_grayscale()).
---@param img datamunge.Image
---@param path string
function datamunge.write_pgm(img, path) end

---Reads a binary (P4) Netpbm bitmap image (1 bit per pixel: set bits are black) as a
---Grayscale image (0 = black, 255 = white). Throws std::runtime_error on a malformed
---file or I/O failure.
---@param path string
---@return datamunge.Image
function datamunge.read_pbm(path) end

---Writes `img` as a binary (P4) Netpbm bitmap, converting to grayscale first and then
---thresholding: pixels with luma strictly below `threshold` become set (black) bits.
---@param img datamunge.Image
---@param path string
---@param threshold? integer (default: `128`)
function datamunge.write_pbm(img, path, threshold) end

---Reads a PNG file as an Image (mode matches the file's color type: Grayscale,
---GrayscaleAlpha, RGB, or RGBA). Only 8-bit-depth, non-interlaced, non-palette PNGs
---are supported (the overwhelming majority of real-world PNGs); indexed-color
---(palette), 16-bit-depth, and Adam7-interlaced files throw std::runtime_error, as
---does a corrupt file (bad signature, chunk CRC mismatch, or truncated/invalid zlib
---stream).
---@param path string
---@return datamunge.Image
function datamunge.read_png(path) end

---Writes `img` as an 8-bit-depth, non-interlaced PNG, using its ImageMode directly as
---the PNG color type (Grayscale/GrayscaleAlpha/RGB/RGBA all have a direct PNG
---equivalent, so no conversion is ever needed). Every scanline is written with filter
---type 0 (None) -- simpler and always correct, at the cost of a somewhat larger file
---than a filter-optimizing encoder would produce; any standard PNG decoder still reads
---the result correctly.
---@param img datamunge.Image
---@param path string
function datamunge.write_png(img, path) end

---Expected improvement of a Gaussian prediction below an incumbent (minimisation).
---
---For `Y\sim N(\mu,\sigma^2)` and target `t=\text{incumbent}-\xi`,
---`\operatorname{E}\max(t-Y,0)=(t-\mu)\Phi(u)+\sigma\varphi(u)` with `u=(t-\mu)/\sigma`.
---
---`\mu`.
---
---`\sigma\ge0`; 0 gives `\max(t-\mu,0)`.
---
---`\xi\ge0` an improvement must exceed.
---
---**Example**
---
---```cpp
---std::print("{:.4f}\n", dm::optim::expected_improvement(0.0, 1.0, 0.0));  // 0.3989 = phi(0)
---```
---@param mean number Predicted mean
---@param sd number Predicted standard deviation
---@param incumbent number Smallest value observed so far.
---@param exploration? number Margin (default: `0.0`)
---@return number # The expected improvement (never negative).
function datamunge.expected_improvement(mean, sd, incumbent, exploration) end

---Probability that a Gaussian prediction falls below incumbent − exploration.
---
---`\mu`.
---
---`\xi\ge0`.
---
---`\Phi\big((\text{incumbent}-\xi-\mu)/\sigma\big)`.
---
---**Example**
---
---```cpp
---std::print("{:.4f}\n", dm::optim::probability_of_improvement(1.0, 1.0, 0.0));  // 0.1587
---```
---@param mean number Predicted mean
---@param sd number Predicted standard deviation; 0 gives 0 or 1.
---@param incumbent number Smallest value observed so far.
---@param exploration? number Margin (default: `0.0`)
---@return number
function datamunge.probability_of_improvement(mean, sd, incumbent, exploration) end

---Classical equal-variance one-way ANOVA, like R oneway.test(var.equal=TRUE).
---
---Tests equality of group means with between/within mean-square ratio. Independent normal
---observations and a common within-group population variance give the exact F reference. This is
---not Welch ANOVA. O(N) work, O(1) auxiliary storage; input unchanged, no omission or shared
---mutable state.
---
---**Example**
---
---```cpp
---const auto a=dm::stats::one_way_anova({1,2,3,4,5,6,7,8,9},{3,3,3});
---std::print("{:.0f}\n",a.statistic); // 27
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/oneway.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Invalid grouping/nonfinite input, no residual df, zero within- group variation or arithmetic overflow.
---
---See also: `HypothesisTestResult`
---@param values number[] Finite observations concatenated group by group.
---@param group_sizes integer[] At least two positive sizes summing exactly to values.size(); N must exceed the group count.
---@return datamunge.HypothesisTestResult # statistic=F, parameter1=k-1, parameter2=N-k and upper-tail p_value; no CI or group estimates.
function datamunge.one_way_anova(values, group_sizes) end

---Tie-corrected Kruskal-Wallis rank test, like R kruskal.test().
---
---Ranks the pooled observations with average ties and uses the chi-square(k-1) approximation.
---The usual exchangeability null is identical independent group distributions; a common-shape
---shift model permits a location interpretation. It is not an omnibus test for every possible
---distributional difference. Small groups can invalidate the approximation. O(N log N) work/O(N)
---space, no mutation, omission or shared state.
---
---**Example**
---
---```cpp
---const auto h=dm::stats::kruskal_wallis_test({1,2,3,4,5,6,7,8,9},{3,3,3});
---std::print("{:.1f}\n",h.statistic); // 7.2
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/kruskal.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Invalid groups, nonfinite input or all observations tied.
---
---See also: `HypothesisTestResult`
---@param values number[] Finite observations concatenated by group.
---@param group_sizes integer[] At least two positive group sizes summing to values.size().
---@return datamunge.HypothesisTestResult # statistic=H, parameter1=k-1 and upper-tail approximate p_value; no CI.
function datamunge.kruskal_wallis_test(values, group_sizes) end

---Pearson chi-square test of specified category probabilities, like R chisq.test().
---
---Uses sum((observed-expected)^2/expected) and chi-square(k-1); the probabilities are fixed, not
---estimated here. Expected counts must be sufficiently large for the approximation. Nonnegative
---fractional counts are accepted algebraically but do not automatically define a sampling model.
---O(k) work/storage, inputs unchanged, no shared state or omission.
---
---**Example**
---
---```cpp
---const auto q=dm::stats::chi_squared_goodness_of_fit({10,10});
---std::print("{:.0f}\n",q.statistic); // 0
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/chisq.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Invalid counts/probabilities, sizes or zero/nonfinite total.
---
---See also: `HypothesisTestResult`
---@param observed number[] At least two finite nonnegative counts with positive finite total.
---@param expected_probabilities? number[] Empty (default) means uniform; otherwise positive finite probabilities matching counts and summing to one within 1e-10. (default: `{}`)
---@return datamunge.HypothesisTestResult # statistic=X-squared, parameter1=k-1 and approximate upper-tail p_value; no CI.
function datamunge.chi_squared_goodness_of_fit(observed, expected_probabilities) end

---Pearson chi-square test for a contingency table, like R chisq.test().
---
---Expected counts are row_sum*column_sum/total; df=(rows-1)(columns-1). The asymptotic reference
---assumes independent multinomial/product-multinomial observations and adequately populated
---expected cells. O(rows*columns) work and O(rows+columns) space; inputs unchanged, no shared
---state.
---
---**Example**
---
---```cpp
---const auto q=dm::stats::chi_squared_test_independence({10,10,10,10},2,2);
---std::print("{:.0f}\n",q.statistic); // 0
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/chisq.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Invalid shape, counts/margins or nonfinite total.
---
---See also: `HypothesisTestResult`
---@param table number[] Finite nonnegative row-major counts with strictly positive margins; integer counts are the usual sampling model.
---@param nrows integer At least two rows.
---@param ncols integer At least two columns; table length must equal nrows*ncols.
---@param correct? boolean True (default) subtracts min(.5,abs(O-E)) from each absolute residual only for 2x2 tables. (default: `true`)
---@return datamunge.HypothesisTestResult # statistic=X-squared, parameter1=df, approximate upper-tail p_value; no CI.
function datamunge.chi_squared_test_independence(table, nrows, ncols, correct) end

---Pearson product-moment correlation test with Fisher-z confidence bounds.
---
---Uses t=r*sqrt((n-2)/(1-r^2)). The exact zero-correlation null reference requires independent
---bivariate-normal pairs; Fisher-z intervals are approximate. At n=3 no confidence interval is
---reported; n>=4 gets one. Perfect correlations use infinite-statistic limits. O(n) work, no
---input mutation/omission or shared state.
---
---**Example**
---
---```cpp
---const auto r=dm::stats::pearson_correlation_test({1,2,3,4},{2,4,6,8});
---std::print("{:.1f}\n",r.estimate1); // 1.0
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/cor.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Invalid lengths, nonfinite/constant samples or invalid controls.
---
---See also: `HypothesisTestResult`
---@param x number[] At least three finite nonconstant first measurements.
---@param y number[] Same-length finite nonconstant second measurements, paired by index.
---@param alternative? datamunge.Alternative TwoSided (default), Less or Greater for population correlation. (default: `datamunge.Alternative.TwoSided`)
---@param conf_level? number Finite confidence level in (0,1), default .95. (default: `0.94999999999999996`)
---@return datamunge.HypothesisTestResult # statistic=t, parameter1=n-2, estimate1=r and p_value; has_conf_int only for n>=4.
function datamunge.pearson_correlation_test(x, y, alternative, conf_level) end

---Spearman correlation with average ranks and a t-approximation p-value.
---
---Computes Pearson correlation on ranks. The reference is always t(n-2), not a small-sample
---exact permutation distribution; ties receive average ranks. Tests zero rank correlation under
---the approximation, not arbitrary independence. O(n log n) work/O(n) storage, no
---mutation/omission or shared state.
---
---**Example**
---
---```cpp
---const auto r=dm::stats::spearman_correlation_test({1,2,3,4},{10,20,30,40});
---std::print("{:.1f}\n",r.estimate1); // 1.0
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/cor.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Invalid lengths, nonfinite/constant samples or alternative.
---
---See also: `HypothesisTestResult`
---@param x number[] At least three finite nonconstant first measurements.
---@param y number[] Same-length finite nonconstant paired second measurements.
---@param alternative? datamunge.Alternative TwoSided (default), Less or Greater for population rank correlation. (default: `datamunge.Alternative.TwoSided`)
---@return datamunge.HypothesisTestResult # statistic=rank-correlation t, parameter1=n-2, estimate1=rho, approximate p_value; no CI.
function datamunge.spearman_correlation_test(x, y, alternative) end

---Kendall rank coefficients by Knight inversion counting.
---
---Sorts paired values and counts concordant, discordant and tied pairs in O(n log n) work/O(n)
---storage. Inputs are unchanged and calls share no mutable state. This is a coefficient
---calculation, not a hypothesis test; tau_b is zero when its denominator vanishes.
---
---**Example**
---
---```cpp
---const auto k=dm::stats::kendall_tau({1,2,3,4},{1,2,3,4});
---std::print("{}\n",k.concordant); // 6
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/cor.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Lengths differ, fewer than two values, or nonfinite observations.
---
---See also: `HypothesisTestResult`
---@param x number[] At least two finite first coordinates.
---@param y number[] Equal-length finite second coordinates, paired by index.
---@return datamunge.KendallTau # Owned pair counts, tau_a and tie-adjusted tau_b.
function datamunge.kendall_tau(x, y) end

---Conditional Fisher exact test of a 2x2 table with fixed margins.
---
---Conditions on row/column totals and tests odds ratio one. Two-sided p-values sum probabilities
---no larger than the observed table (relative ordering tolerance 1e-7); they are not generally
---twice the smaller tail. Direct tail summation avoids 1-CDF cancellation. Empty margins give
---p=1. O(s) work/O(1) auxiliary storage for feasible support s; inputs unchanged, no shared
---state.
---
---**Example**
---
---```cpp
---const auto f=dm::stats::fisher_exact_test_2x2(0,3,3,0);
---std::print("{:.1f}\n",f.p_value); // 0.1
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/fisher.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Count-total overflow or invalid alternative.
---
---See also: `HypothesisTestResult`
---@param a integer Top-left nonnegative integer count.
---@param b integer Top-right count.
---@param c integer Bottom-left count.
---@param d integer Bottom-right count; total must fit size_t.
---@param alternative? datamunge.Alternative TwoSided (default), Less or Greater for the odds ratio relative to one. (default: `datamunge.Alternative.TwoSided`)
---@return datamunge.HypothesisTestResult # statistic=a, p_value and estimate1=sample odds ratio a*d/(b*c), not R conditional MLE; denominator zero gives infinity for positive numerator or NaN for 0/0. No confidence interval.
function datamunge.fisher_exact_test_2x2(a, b, c, d, alternative) end

---One-sample KS test against a fully specified continuous normal CDF.
---
---Two-sided p-values use the Stephens corrected asymptotic Kolmogorov reference; one-sided
---values use exp(-2*n*D^2). Mean and sd must be fixed independently of this sample: fitting them
---here invalidates the stated calibration. This is not a Lilliefors test. Ties are accepted, but
---continuous-null calibration is affected by rounding. O(n log n) work/O(n) storage, input
---unchanged, no omission/shared state.
---
---**Example**
---
---```cpp
---const auto k=dm::stats::ks_test_one_sample_normal({-1,0,1});
---std::print("{:.0f}\n",k.parameter1); // 3
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/ks.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Too few/nonfinite values, invalid mean/sd or alternative.
---
---See also: `HypothesisTestResult`
---@param x number[] At least two finite observations.
---@param mean? number Finite prespecified normal mean, default zero. (default: `0.0`)
---@param sd? number Positive finite prespecified normal SD, default one. (default: `1.0`)
---@param alternative? datamunge.Alternative TwoSided (default); Greater tests empirical CDF above reference, Less below (opposite to a location alternative). (default: `datamunge.Alternative.TwoSided`)
---@return datamunge.HypothesisTestResult # statistic=D or D+/D-, parameter1=n and approximate p_value; no CI.
function datamunge.ks_test_one_sample_normal(x, mean, sd, alternative) end

---One-sample KS test against a specified continuous uniform CDF.
---
---Same asymptotic p-value and tie caveats as ks_test_one_sample_normal(); limits must be
---prespecified rather than estimated from x. O(n log n) work/O(n) storage; no mutation, omission
---or shared state.
---
---**Example**
---
---```cpp
---const auto k=dm::stats::ks_test_one_sample_uniform({.2,.4,.6,.8});
---std::print("{:.1f}\n",k.statistic); // 0.2
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/ks.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Invalid sample, limits or alternative.
---
---See also: `HypothesisTestResult`
---@param x number[] At least two finite observations.
---@param lower? number Finite prespecified lower bound, default zero. (default: `0.0`)
---@param upper? number Finite upper bound greater than lower, default one. (default: `1.0`)
---@param alternative? datamunge.Alternative TwoSided (default), Greater for empirical CDF above reference or Less below. (default: `datamunge.Alternative.TwoSided`)
---@return datamunge.HypothesisTestResult # statistic=D or D+/D-, parameter1=n, approximate p_value; no CI.
function datamunge.ks_test_one_sample_uniform(x, lower, upper, alternative) end

---Two-sample KS comparison of empirical CDFs with asymptotic p-values.
---
---Uses effective n=n_x*n_y/(n_x+n_y) in the asymptotic reference. This is not an exact finite-
---sample calculation; ties/rounding and very small groups affect calibration. O(N log N)
---work/O(N) storage; inputs unchanged, no omission/shared state.
---
---**Example**
---
---```cpp
---const auto k=dm::stats::ks_test_two_sample({1,2,3},{1,2,3});
---std::print("{:.0f}\n",k.statistic); // 0
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/ks.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Empty/nonfinite samples or invalid alternative.
---
---See also: `HypothesisTestResult`
---@param x number[] Nonempty finite first sample.
---@param y number[] Nonempty finite independent second sample.
---@param alternative? datamunge.Alternative TwoSided (default); Greater tests F_x above F_y, Less below, so Greater corresponds to stochastically smaller x. (default: `datamunge.Alternative.TwoSided`)
---@return datamunge.HypothesisTestResult # statistic=D or D+/D-, parameter1=n_x, parameter2=n_y and approximate p_value; no CI.
function datamunge.ks_test_two_sample(x, y, alternative) end

---Shapiro-Francia composite normality test, like R nortest::sf.test().
---
---Squared correlation of sorted observations with Blom normal scores, using Royston (1993) log-
---normal p-value approximation. Tests some normal distribution; a large p-value does not prove
---normality. Rounding/ties affect calibration. O(n log n) work/O(n) storage; input unchanged, no
---omission/shared state.
---
---**Example**
---
---```cpp
---const auto s=dm::stats::shapiro_francia_test({1,2,3,4,5});
---std::print("{}\n",s.has_conf_int); // false
---```
---
---**References**
---
---- https://search.r-project.org/CRAN/refmans/nortest/html/sf.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Invalid sample size, nonfinite input or constant sample.
---
---See also: `HypothesisTestResult`
---@param x number[] Between 5 and 5000 finite, nonconstant observations.
---@return datamunge.HypothesisTestResult # statistic=estimate1=W-prime and approximate p_value; no CI.
function datamunge.shapiro_francia_test(x) end

---Adjust a vector of p-values for multiple comparisons, matching R's p.adjust().
---
---- Bonferroni: p[i] * n, capped at 1 -- simplest and most conservative FWER control.
---- Holm: step-down Bonferroni (Holm-Bonferroni) -- uniformly more powerful than
---  plain Bonferroni while still controlling FWER, no extra assumptions.
---- Hochberg: step-up FWER control -- more powerful than Holm, but assumes the test
---  statistics are independent (or positively dependent).
---- Hommel: step-up FWER control, uniformly more powerful than Hochberg under the
---  same independence assumption; the most expensive to compute (O(n^2)). For n == 2
---  this degenerates to (and is computed as) Hochberg, matching R.
---- BH (Benjamini-Hochberg, aka "fdr" in R): controls the false discovery rate under
---  independence or positive regression dependence -- the standard choice for large-
---  scale testing (e.g. genomics, many simultaneous hypothesis tests).
---- BY (Benjamini-Yekutieli): controls the FDR under arbitrary dependence; more
---  conservative than BH.
---- None: returns the input p-values unchanged.
---
---As in R, a single p-value (n <= 1) is always returned unchanged regardless of
---`method`.
---@param p number[]
---@param method? datamunge.PAdjustMethod (default: `datamunge.PAdjustMethod.BH`)
---@return number[]
function datamunge.p_adjust(p, method) end

---Westfall-Young single-step minP adjustment (Westfall & Young, 1993) -- a resampling-
---based FWER correction that accounts for the actual dependence structure between
---tests (unlike the analytic methods above, which either assume independence or make
---no assumption at all).
---
---`resampled_p` is a B x m matrix: row b holds the m p-values recomputed on the
---b-th permutation or bootstrap resample (generated by the caller -- this function is
---purely the combinatorial engine, not the resampling scheme itself). `sorted_p` is
---the m original p-values sorted ascending, and column k of every row in `resampled_p`
---must correspond to the same hypothesis as sorted_p[k] (i.e. the caller sorts once and
---reorders both consistently before calling).
---
---Single-step: every hypothesis is compared against the same reference distribution --
---the per-resample minimum p-value taken over *all* m hypotheses -- so adjusted p[k] =
---(fraction of resamples whose overall minimum p-value <= sorted_p[k]). This is
---automatically monotonic in sorted_p and valid under subset pivotality, but less
---powerful than the step-down refinement below since it never narrows the comparison
---set as hypotheses are resolved.
---
---Returned in the same (ascending sorted_p) order as the input; the caller is
---responsible for mapping back to original hypothesis order if needed.
---@param resampled_p number[][]
---@param sorted_p number[]
---@return number[]
function datamunge.westfall_young_adjust(resampled_p, sorted_p) end

---Romano-Wolf step-down resampling adjustment (Romano & Wolf, 2005) -- like
---westfall_young_adjust, but more powerful: at each step k (in ascending sorted_p
---order), the reference distribution is the per-resample minimum p-value taken only
---over the *remaining* hypotheses k..m-1, narrowing by one hypothesis at each step
---rather than always using all m. This is the step-down generalization that controls
---FWER without requiring subset pivotality. Monotonicity (adjusted p[k] >= adjusted
---p[k-1]) is enforced explicitly, since narrowing the comparison set at each step means
---it isn't automatic the way it is for the single-step procedure above.
---
---Same input/output conventions as westfall_young_adjust: `resampled_p` is a B x m
---matrix with column k aligned to sorted_p[k], and the result is returned in the same
---sorted order.
---@param resampled_p number[][]
---@param sorted_p number[]
---@return number[]
function datamunge.romano_wolf_adjust(resampled_p, sorted_p) end

---One-proportion score test with an uncorrected Wilson confidence interval.
---
---Tests a fixed Bernoulli success probability using the signed null-standard-error z statistic;
---statistic stores z^2 but the chosen tail uses its sign. The optional continuity correction
---affects the test only: its Wilson interval is uncorrected and need not invert that test.
---Approximation requires sufficiently populated success/failure counts. O(1) work/storage, no
---shared state.
---
---**Example**
---
---```cpp
---const auto p=dm::stats::proportion_test_one_sample(45,100);
---std::print("{:.2f}\n",p.estimate1); // 0.45
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/prop.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Invalid counts, null probability, alternative or confidence level.
---
---See also: `HypothesisTestResult`
---@param successes integer Integer successes in [0,n].
---@param n integer Positive independent-trial count.
---@param p? number Finite null probability strictly in (0,1), default .5. (default: `0.5`)
---@param alternative? datamunge.Alternative TwoSided (default), Less or Greater for true probability relative to p. (default: `datamunge.Alternative.TwoSided`)
---@param correct? boolean True (default) applies the capped half-count correction to z. (default: `true`)
---@param conf_level? number Finite confidence level in (0,1), default .95. (default: `0.94999999999999996`)
---@return datamunge.HypothesisTestResult # statistic=z^2, parameter1=1, estimate1=successes/n, p_value and uncorrected Wilson confidence bounds.
function datamunge.proportion_test_one_sample(successes, n, p, alternative, correct, conf_level) end

---Pooled score test for two proportions, with an unpooled difference interval.
---
---Tests equality using the pooled null SE and optionally a capped continuity correction. The
---difference CI uses an unpooled Wald SE and an uncapped half-count width correction when
---requested; it is approximate and is not a Wilson/Newcombe interval. All-zero/all-one pooled
---samples return z=0,p=1. O(1) work/storage, no shared state.
---
---**Example**
---
---```cpp
---const auto p=dm::stats::proportion_test_two_sample(2,10,3,10);
---std::print("{:.1f}\n",p.estimate1); // 0.2
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/prop.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Invalid counts, alternative or confidence level.
---
---See also: `HypothesisTestResult`
---@param successes1 integer First success count in [0,n1].
---@param n1 integer Positive first independent-trial count.
---@param successes2 integer Second success count in [0,n2].
---@param n2 integer Positive independent second-trial count.
---@param alternative? datamunge.Alternative TwoSided (default), Less or Greater for p1-p2. (default: `datamunge.Alternative.TwoSided`)
---@param correct? boolean True (default) corrects the score test and adds a half-count CI width. (default: `true`)
---@param conf_level? number Finite confidence level in (0,1), default .95. (default: `0.94999999999999996`)
---@return datamunge.HypothesisTestResult # statistic=z^2, parameter1=1, estimates=sample proportions, p_value and confidence bounds for p1-p2, clamped to [-1,1].
function datamunge.proportion_test_two_sample(successes1, n1, successes2, n2, alternative, correct, conf_level) end

---Exact binomial test with Clopper-Pearson confidence bounds, like R binom.test().
---
---One-sided p-values are inclusive tails. Two-sided p-values sum PMFs no larger than the
---observed PMF, using relative comparison tolerance 1e-7. The equal-tailed Clopper-Pearson
---interval has at-least-nominal coverage but need not invert the probability-ordered two-sided
---test. Null endpoints zero/one are supported. Two-sided enumeration costs O(n), intervals use
---bounded beta-CDF bisection; O(1) auxiliary storage, no shared state.
---
---**Example**
---
---```cpp
---const auto b=dm::stats::binomial_test(9,10);
---std::print("{:.6f}\n",b.p_value); // 0.021484
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/binom.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Invalid counts, probability, alternative or confidence level.
---
---See also: `HypothesisTestResult`
---@param successes integer Integer observed successes in [0,n].
---@param n integer Positive independent Bernoulli trial count.
---@param p? number Finite null probability in [0,1], default .5. (default: `0.5`)
---@param alternative? datamunge.Alternative TwoSided (default), Less or Greater for true success probability. (default: `datamunge.Alternative.TwoSided`)
---@param conf_level? number Finite confidence level in (0,1), default .95. (default: `0.94999999999999996`)
---@return datamunge.HypothesisTestResult # statistic=successes, parameter1=n, estimate1=successes/n, p_value and Clopper-Pearson interval; one-sided intervals end at zero/one.
function datamunge.binomial_test(successes, n, p, alternative, conf_level) end

---One-sample Student t-test of a population mean, like R t.test().
---
---Independent normal observations give t=(mean-mu)/SE with n-1 df. The CI estimates the
---population mean, not mean-mu. Inputs are copied only for paired differences; all routines
---leave inputs unchanged and use no shared mutable state. O(n) work; no null/nonfinite omission.
---
---**Example**
---
---```cpp
---const auto t=dm::stats::t_test_one_sample({1,2,3,4});
---std::print("{:.0f}\n",t.parameter1); // 3
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/t.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Too few/nonfinite values, invalid mu/alternative/confidence or zero/nonfinite standard error.
---
---See also: `HypothesisTestResult`
---@param x number[] At least two finite observations with positive representable sample variance.
---@param mu? number Finite null mean, default zero, in observation units. (default: `0.0`)
---@param alternative? datamunge.Alternative TwoSided (default), Less or Greater, relative to mu. (default: `datamunge.Alternative.TwoSided`)
---@param conf_level? number Finite confidence level strictly in (0,1), default .95. (default: `0.94999999999999996`)
---@return datamunge.HypothesisTestResult # statistic=t, parameter1=df, estimate1=sample mean, p_value and mean confidence bounds; remaining scalars retain defaults. One-sided intervals have one infinite endpoint.
function datamunge.t_test_one_sample(x, mu, alternative, conf_level) end

---Independent two-sample Welch or pooled Student mean test, like R t.test().
---
---Welch uses unequal sample variances and Satterthwaite approximate df; normality alone does not
---make its reference exact. Pooled Student requires equal population variances and independent
---normal observations for its exact reference. CI estimates mean(x)-mean(y). O(n_x+n_y) work,
---inputs unchanged, no shared mutable state or omission.
---
---**Example**
---
---```cpp
---const auto t=dm::stats::t_test_two_sample({1,2,3},{4,5,6});
---std::print("{:.0f}\n",t.estimate1); // 2
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/t.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Invalid sample sizes/values, alternative/confidence, unrepresentable mean difference or zero/nonfinite combined standard error.
---
---See also: `HypothesisTestResult`
---@param x number[] At least two finite observations in the first group.
---@param y number[] At least two finite independent observations in the second group.
---@param equal_variance? boolean False (default) uses Welch; true uses pooled variance. (default: `false`)
---@param alternative? datamunge.Alternative TwoSided (default), Less or Greater for mean(x)-mean(y). (default: `datamunge.Alternative.TwoSided`)
---@param conf_level? number Finite confidence level in (0,1), default .95. (default: `0.94999999999999996`)
---@return datamunge.HypothesisTestResult # statistic=t, parameter1=df, estimate1/2=group means, p_value and confidence bounds for their difference. One-sided bounds can be infinite.
function datamunge.t_test_two_sample(x, y, equal_variance, alternative, conf_level) end

---Paired Student t-test on aligned differences, like R t.test(paired=TRUE).
---
---Runs the one-sample test on x[i]-y[i]. Differences, rather than the two marginal samples, need
---independent normal sampling for the exact t reference. Row order defines pairing; no values
---are omitted. O(n) work/storage; inputs unchanged, no shared mutable state.
---
---**Example**
---
---```cpp
---const auto t=dm::stats::t_test_paired({2,4,7},{1,2,4});
---std::print("{:.0f}\n",t.parameter1); // 2
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/t.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Length mismatch, nonfinite data/differences, invalid controls or zero/nonfinite difference standard error.
---
---See also: `HypothesisTestResult`
---@param x number[] At least two finite first measurements.
---@param y number[] Equal-length finite second measurements paired by index.
---@param alternative? datamunge.Alternative TwoSided (default), Less or Greater for the population mean difference. (default: `datamunge.Alternative.TwoSided`)
---@param conf_level? number Finite confidence level in (0,1), default .95. (default: `0.94999999999999996`)
---@return datamunge.HypothesisTestResult # One-sample difference result with method Paired t-test; estimate1 is mean difference, CI targets the same difference.
function datamunge.t_test_paired(x, y, alternative, conf_level) end

---F-test and interval for a ratio of variances, like R var.test().
---
---Uses sample variance(x)/sample variance(y). Independent normal populations give the
---F(df_x,df_y) reference; it is sensitive to nonnormality and is not a gatekeeper for choosing
---Welch versus pooled t tests. O(n_x+n_y) work/O(1) auxiliary storage; inputs unchanged, no
---omission/shared state.
---
---**Example**
---
---```cpp
---const auto f=dm::stats::f_test_variance({1,2,3},{2,4,6});
---std::print("{:.2f}\n",f.estimate1); // 0.25
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/var.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Too few/nonfinite observations, nonpositive/nonfinite variances or invalid controls.
---
---See also: `HypothesisTestResult`
---@param x number[] At least two finite first-sample values with positive finite sample variance.
---@param y number[] At least two finite independent second-sample values with positive finite sample variance.
---@param alternative? datamunge.Alternative TwoSided (default), Less or Greater for population variance ratio relative to one. (default: `datamunge.Alternative.TwoSided`)
---@param conf_level? number Finite confidence level in (0,1), default .95. (default: `0.94999999999999996`)
---@return datamunge.HypothesisTestResult # statistic=estimate1=variance ratio, parameter1/2=sample sizes minus one, p_value and ratio confidence bounds; one-sided interval ends at zero or infinity.
function datamunge.f_test_variance(x, y, alternative, conf_level) end

---Normal-approximation Wilcoxon signed-rank test with tie/continuity corrections.
---
---Tests symmetry of x-mu about zero under independent observations, not an arbitrary-population
---mean or median null. For paired data pass aligned differences. Exact-zero differences are
---removed; absolute differences receive average ranks. Always uses a normal approximation, even
---for small tie-free samples; no exact option or CI. O(n log n) work/O(n) storage; input
---unchanged, no shared state.
---
---**Example**
---
---```cpp
---const auto w=dm::stats::wilcoxon_signed_rank_test({1,2,3,4});
---std::print("{:.0f}\n",w.statistic); // 10
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/wilcox.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Nonfinite input/mu, invalid alternative, no nonzero differences or zero rank variance.
---
---See also: `HypothesisTestResult`
---@param x number[] Finite values; at least one nonzero difference from mu must remain.
---@param mu? number Finite symmetry centre, default zero. (default: `0.0`)
---@param alternative? datamunge.Alternative TwoSided (default), Less or Greater for the signed location shift. (default: `datamunge.Alternative.TwoSided`)
---@return datamunge.HypothesisTestResult # statistic=positive rank sum V, estimate1=mu (not an estimated pseudomedian), approximate p_value; no CI.
function datamunge.wilcoxon_signed_rank_test(x, mu, alternative) end

---Tie/continuity-corrected Mann-Whitney U test using a normal approximation.
---
---Pools ranks, giving average ranks to ties, and reports U for the first sample. Its identical-
---distribution null requires independent exchangeable samples. A common-shape shift model
---supports a location interpretation; equal medians alone is insufficient. U/(n_x*n_y) estimates
---P(X>Y)+P(X=Y)/2, not a mean difference. Approximation is used at every size. O(N log N)
---work/O(N) storage, inputs unchanged, no shared state.
---
---**Example**
---
---```cpp
---const auto w=dm::stats::wilcoxon_rank_sum_test({1,2,3},{4,5,6});
---std::print("{:.0f}\n",w.statistic); // 0
---```
---
---**References**
---
---- https://stat.ethz.ch/R-manual/R-devel/library/stats/html/wilcox.test.html
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: Empty/nonfinite samples, invalid alternative or zero rank variance (all pooled observations tied).
---
---See also: `HypothesisTestResult`
---@param x number[] Nonempty finite first sample.
---@param y number[] Nonempty finite independent second sample.
---@param alternative? datamunge.Alternative TwoSided (default), Less or Greater for first-versus-second stochastic location. (default: `datamunge.Alternative.TwoSided`)
---@return datamunge.HypothesisTestResult # statistic=U=rank_sum(x)-n_x(n_x+1)/2 and approximate p_value; no CI or location estimate.
function datamunge.wilcoxon_rank_sum_test(x, y, alternative) end

---Construct an owned B-spline basis for repeated evaluation with eval().
---Free-function spelling of Bspline: construction fixes the knots and boundaries
---without evaluating a design matrix or fitting a model. The returned value owns
---its basis; the input knot vector may be modified or destroyed after this call.
---
---**Example**
---
---```cpp
---const auto basis = dm::bs(0, 1, dm::seql(0, 1, 3));
---const auto design = basis.eval(dm::c(0, 0.5, 1));
---std::print("{} {}\n", design.rows(), design.cols()); // 3 4
---```
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: For invalid boundaries, knots or overflowing degree.
---
---See also: `Bspline`, `Bspline::eval()`
---@param lower number Finite left boundary, strictly below upper.
---@param upper number Finite right boundary.
---@param knots number[] Finite, strictly increasing breakpoints in [lower, upper]. Boundary entries are optional; an empty vector creates a basis without interior knots.
---@param degree? integer Polynomial degree, default 3 (cubic). (default: `3`)
---@param intercept? boolean Keep the first basis column, default false. Leave false with an intercept formula such as `y ~ .`; use a no-intercept formula when true. (default: `false`)
---@return datamunge.Bspline # Owned Bspline with the same degree, intercept policy and validation as its constructor. Call eval() on training and prediction coordinates.
function datamunge.bs(lower, upper, knots, degree, intercept) end

---Create a directory and any missing parent directories.
---Accepts native filesystem paths, strings and string literals. An existing
---directory is a successful no-op; an existing file at the target or along its
---parents is an error. Relative paths use the current working directory, which
---this function does not change. Permissions follow the native filesystem and
---process defaults. A failed recursive operation may leave created parents.
---This C++ convenience forwards to std::filesystem::create_directories().
---
---**Example**
---
---```cpp
---dm::mkdir("build/figs");
---std::print("{}\n", std::filesystem::is_directory("build/figs")); // true
---```
---
---**Errors** (raised as Lua errors)
---* `std::filesystem::filesystem_error`: For an empty path, a conflicting file, insufficient permissions or other operating-system filesystem errors.
---
---See also: `std::filesystem::create_directories()`
---@param path string Directory to create, including any missing parents; must not be empty.
---@return boolean # True if the target directory was created, false if it already existed.
function datamunge.mkdir(path) end

---Prints a hello message to standard output.
function datamunge.hello() end

---Invokes a callback with the given value.
---@param x number Input value passed to the callback.
---@param cb datamunge.Callback? Pointer to a `Callback` instance; must not be null.
---@return number # Result of `cb->call(x)`.
function datamunge.call_with_callback(x, cb) end

---Applies a callback to every element of a vector.
---@param values number[] Source vector of doubles.
---@param cb datamunge.Callback? Pointer to a `Callback` instance; must not be null.
---@return number[] # New vector where each element is the result of `cb->call(v)` for the corresponding element `v` in `values`.
function datamunge.map_dvector_with_callback(values, cb) end

---Constructs a three-element vector from individual values.
---@param a number First element.
---@param b number Second element.
---@param c number Third element.
---@return number[] # `std::vector<double>{a`, b, c}.
function datamunge.make_dvector(a, b, c) end

---Computes the sum of all elements in a vector.
---@param values number[] Vector of doubles to sum.
---@return number # Sum of all elements, or 0.0 if the vector is empty.
function datamunge.sum_dvector(values) end

---Constructs a pair of doubles.
---@param a number First element.
---@param b number Second element.
---@return [number, number] # `std::pair<double`, double>{a, b}.
function datamunge.make_dpair(a, b) end

---Computes the sum of both elements in a pair.
---@param values [number, number] Pair of doubles.
---@return number # `values.first` + values.second.
function datamunge.sum_dpair(values) end

---Inserts knots into a clamped B-spline basis (Oslo algorithm).
---
---Builds the refined knot vector (old knots merged with `inserted_knots`) and the sparse
---discrete-B-spline operator that re-expresses every coarse spline on it exactly. Each
---row has at most degree + 1 nonzeros and the work is O(m p^2) for m refined functions.
---
---**Example**
---
---```cpp
---auto coarse = dm::fda::BSplineBasis::open_uniform(1, 2);   // knots 0 0 1 1
---auto r = dm::fda::refine_basis(coarse, {0.25});
---std::print("{}\n", r.apply({0.0, 4.0}));                   // [0, 1, 4]
---```
---
---**References**
---
---- E. Cohen, T. Lyche and R. Riesenfeld (1980). Discrete B-splines and subdivision
---  techniques in computer-aided geometric design and computer graphics. Computer Graphics
---  and Image Processing 14(2), 87-111. https://doi.org/10.1016/0146-664X(80)90040-4
---- W. Boehm (1980). Inserting new knots into B-spline curves. Computer-Aided Design
---  12(4), 199-201. https://doi.org/10.1016/0010-4485(80)90154-2
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: If the basis is not clamped, a knot is outside the open domain or non-finite, or a multiplicity would exceed degree + 1.
---
---See also: `dyadic_refine()`
---@param basis datamunge.BSplineBasis Basis to refine; its knot vector must be clamped (first and last knots repeated degree + 1 times, as produced by BSplineBasis::open_uniform()).
---@param inserted_knots number[] Knots to add, strictly inside the domain, in any order. Repeats are allowed while every knot multiplicity stays <= degree + 1.
---@return datamunge.BSplineRefinement # The refined basis and its refinement operator.
function datamunge.refine_basis(basis, inserted_knots) end

---Halves every knot span of a clamped basis (inserts each positive span's midpoint).
---
---This is the nested-space step between consecutive levels of HB/THB splines: the refined
---space contains the coarse one, and the operator maps coefficients exactly.
---
---**Example**
---
---```cpp
---auto r = dm::fda::dyadic_refine(dm::fda::BSplineBasis::open_uniform(3, 5));
---std::print("{} -> {}\n", 5, r.basis.basis_size()); // 5 -> 7
---```
---
---**References**
---
---- E. Cohen, T. Lyche and R. Riesenfeld (1980). Discrete B-splines and subdivision
---  techniques in computer-aided geometric design and computer graphics.
---  https://doi.org/10.1016/0146-664X(80)90040-4
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: If the basis is not clamped.
---
---See also: `refine_basis()`, `TensorBSpline::dyadic_refine()`
---@param basis datamunge.BSplineBasis Clamped basis to refine.
---@return datamunge.BSplineRefinement # The refined basis and its refinement operator.
function datamunge.dyadic_refine(basis) end

---Fits a tensor-product B-spline to scattered data by ordinary least squares.
---
---Builds the sparse design B (each row has at most prod(degree_k + 1) nonzeros), then
---solves (B^T B) c = B^T y. Coordinates outside a basis domain are clamped to it.
---
---**Example**
---
---```cpp
---auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
---auto f = dm::fda::fit_tensor_bspline({b}, {{0.0}, {0.5}, {1.0}}, {1.0, 2.0, 3.0});
---std::print("{:.3f}\n", f.evaluate(0.25)); // 1.500
---```
---
---**References**
---
---- C. de Boor (2001). A Practical Guide to Splines, revised edition. Springer.
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: On empty or mismatched inputs, or non-finite data.
---* `std::runtime_error`: If the normal equations are singular (some basis function has too little data; use a penalized fit or fewer functions).
---
---See also: `fit_tensor_pspline()`
---@param bases datamunge.BSplineBasis[] One basis per dimension.
---@param points number[][] Sample locations, each of length bases.size().
---@param values number[] One response per point.
---@param options? datamunge.SplineSolveOptions Solver settings (default: automatic). (default: `datamunge.SplineSolveOptions()`)
---@return datamunge.TensorBSpline # The fitted spline.
function datamunge.fit_tensor_bspline(bases, points, values, options) end

---Fits a tensor-product P-spline: least squares plus an anisotropic difference
---penalty, solving (B^T B + P) c = B^T y with P from tensor_difference_penalty().
---
---All-zero lambdas reproduce fit_tensor_bspline(). Positive lambdas keep the system
---well-posed even with fewer points than coefficients (for order 0, or once the data
---determine the order-q polynomial null space).
---
---**Example**
---
---```cpp
---auto b = dm::fda::BSplineBasis::open_uniform(3, 8);
---auto f = dm::fda::fit_tensor_pspline({b}, {{0.0}, {1.0}}, {0.0, 1.0}, {1e3});
---std::print("{:.3f}\n", f.evaluate(0.5)); // 0.500
---```
---
---**References**
---
---- P. H. C. Eilers and B. D. Marx (1996). Flexible smoothing with B-splines and penalties.
---  https://doi.org/10.1214/ss/1038425655
---- P. H. C. Eilers, I. D. Currie and M. Durban (2006). Fast and compact smoothing on large
---  multidimensional grids. https://doi.org/10.1016/j.csda.2004.07.008
---
---**Errors** (raised as Lua errors)
---* `std::invalid_argument`: On empty/mismatched inputs, invalid lambdas, or an axis with no more functions than `order`.
---* `std::runtime_error`: If the penalized normal equations are singular.
---
---See also: `fit_tensor_bspline()`, `fit_pspline()`
---@param bases datamunge.BSplineBasis[] One basis per dimension.
---@param points number[][] Sample locations, each of length bases.size().
---@param values number[] One response per point.
---@param lambdas number[] Nonnegative per-axis smoothing weights, one per basis.
---@param order? integer Difference order (default 2, the conventional curvature penalty). (default: `2`)
---@param options? datamunge.SplineSolveOptions Solver settings (default: automatic). (default: `datamunge.SplineSolveOptions()`)
---@return datamunge.TensorBSpline # The fitted spline.
function datamunge.fit_tensor_pspline(bases, points, values, lambdas, order, options) end

